<?php
require_once __DIR__ . '/includes/functions.php'; require_login();
$page_title='Dashboard Instansi';$active_page='dashboard';
$total=(int)db()->query('SELECT COUNT(*) FROM activities')->fetchColumn();
$todayCount=(int)db()->query('SELECT COUNT(*) FROM activities WHERE activity_date=CURDATE()')->fetchColumn();
$memberCount=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();
$photoCount=(int)db()->query('SELECT COUNT(*) FROM activity_photos')->fetchColumn();
$weekRows=db()->query('SELECT DATE(activity_date) AS day,COUNT(*) AS total FROM activities WHERE activity_date>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(activity_date) ORDER BY day')->fetchAll();
$weekMap=[];foreach($weekRows as $r)$weekMap[$r['day']]=(int)$r['total'];
$recent=db()->query('SELECT a.id,a.title,a.activity_date,a.activity_time,a.category,a.location,a.description,u.name AS user_name,u.department,(SELECT p.id FROM activity_photos p WHERE p.activity_id=a.id ORDER BY p.id LIMIT 1) AS cover_photo_id,(SELECT COUNT(*) FROM activity_photos p2 WHERE p2.activity_id=a.id) AS photo_count FROM activities a JOIN users u ON u.id=a.user_id ORDER BY a.activity_date DESC,a.activity_time DESC,a.id DESC LIMIT 6')->fetchAll();
$topCategory=db()->query('SELECT category,COUNT(*) AS total FROM activities GROUP BY category ORDER BY total DESC,category ASC LIMIT 1')->fetch();
$topContributor=db()->query('SELECT u.name,COUNT(a.id) AS total FROM users u LEFT JOIN activities a ON a.user_id=u.id AND a.activity_date>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY u.id ORDER BY total DESC,u.name ASC LIMIT 1')->fetch();
$weekMax=max(1,max($weekMap?:[0]));
require __DIR__ . '/partials/header.php';
?>
