<section class="panel"><div class="panel-head"><div><h3>Aktivitas 7 hari terakhir</h3><p>Jumlah kegiatan berdasarkan tanggal.</p></div></div><div class="week-chart"><?php for($i=6;$i>=0;$i--):$d=date('Y-m-d',strtotime('-'.$i.' day'));$count=$weekMap[$d]??0;$height=$count?max(8,(int)round(($count/$weekMax)*100)):4; ?><div class="week-bar-item"><div class="week-bar-track"><div class="week-bar" style="height:<?= $height ?>%" title="<?= $count ?> kegiatan"></div></div><strong><?= $count ?></strong><span><?= e(date('D',strtotime($d))) ?></span></div><?php endfor; ?></div><div class="insight-box"><span class="insight-icon">✦</span><div><strong><?= e($topCategory['category']??'Belum ada kategori') ?></strong><p><?= $topCategory?(int)$topCategory['total'].' kegiatan pada kategori terbanyak':'Kategori akan muncul setelah kegiatan dicatat.' ?></p></div></div><div class="insight-box"><span class="insight-icon">♙</span><div><strong><?= e($topContributor['name']??'Belum ada anggota') ?></strong><p><?= (int)($topContributor['total']??0) ?> kegiatan dalam 7 hari terakhir</p></div></div><a href="gallery.php" class="btn btn-secondary btn-block">Buka galeri dokumentasi →</a></section></div>
